var minEnd = function(n, x) {
    let answer = BigInt(x);
    let remaining = BigInt(n - 1);
    let bit = 1n;
    while (remaining > 0n) {
        if ((answer & bit) === 0n) {
            if ((remaining & 1n) !== 0n) answer |= bit;
            remaining >>= 1n;
        }
        bit <<= 1n;
    }
    return Number(answer);
};

